/**
 * Milestone state errors and the name rule they enforce.
 *
 * `MilestoneStateError` is the one conflict raised by milestone operations: a
 * milestone in the wrong state for the call, a name already taken in its
 * project, or the open-milestone cap. `toAppError()` maps it to `conflict`.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const DEFAULT_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "The milestone is closed.",
  already_open: "The milestone is already open.",
  too_many_open: "The project already has the maximum number of open milestones.",
  name_taken: "A milestone with that name already exists in this project.",
};

export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    message: string = DEFAULT_MESSAGES[reason],
  ) {
    super(message);
    this.name = "MilestoneStateError";
  }
}

/**
 * The uniqueness key for a milestone name within its project. Letter case and
 * surrounding spaces are not significant, so `" Beta "` and `"beta"` collide.
 */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

