/**
 * Milestone rows, the name lookup behind their uniqueness rule, and the live-issue counts behind their progress.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, milestoneNameKey, toMilestone, CLOSED_ISSUE_STATUSES
 */
import { and, asc, count, eq, inArray, isNotNull, isNull, not, sql } from "drizzle-orm";
import { milestoneNameKey } from "@/lib/milestones";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** The milestone of this project that already holds `name` (closed ones included), if any. */
export async function findMilestoneByName(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.nameKey, milestoneNameKey(name)),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, closed ones included, in creation order. */
export async function listMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(milestones.createdAt), asc(sql`rowid`))
    .all();
  return rows.map(toMilestone);
}

/** Open milestones are the ones with no `closed_at`; closed ones do not count against the cap. */
export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      nameKey: milestoneNameKey(input.name),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

/** `undefined` leaves a field alone; `null` clears the target date. */
export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    readonly name?: string;
    readonly targetDate?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined
        ? {}
        : { name: patch.name, nameKey: milestoneNameKey(patch.name) }),
      ...(patch.targetDate === undefined
        ? {}
        : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes a milestone and moves its open live issues to `moveTo` (or out of any
 * milestone when `null`), in one transaction. Closed and archived issues stay
 * where they are. The issue set is read inside the transaction, so it is the
 * set that actually moves.
 */
export function closeMilestoneRow(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
  stamp: IsoTimestamp,
): { readonly milestone: Milestone; readonly movedIssueIds: readonly IssueId[] } {
  return getDb().transaction((tx) => {
    const movedIssueIds = tx
      .select({ id: issues.id })
      .from(issues)
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, orgId),
            eq(issues.milestoneId, milestoneId),
            livePredicate(issues.archivedAt, {}),
            not(inArray(issues.status, [...CLOSED_ISSUE_STATUSES])),
          ),
        ),
      )
      .all()
      .map((row) => row.id as IssueId);

    if (movedIssueIds.length > 0) {
      tx.update(issues)
        .set({ milestoneId: moveTo, updatedAt: stamp })
        .where(inArray(issues.id, [...movedIssueIds]))
        .run();
    }

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .returning()
      .get();

    return { milestone: toMilestone(row), movedIssueIds };
  });
}

/**
 * Progress for the milestones of one project, keyed by milestone id. Counts
 * live issues in a single grouped read, so no page size can truncate them.
 * A milestone with no live issues is absent from the map.
 */
export async function countMilestoneIssues(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId?: MilestoneId,
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          milestoneId === undefined
            ? undefined
            : eq(issues.milestoneId, milestoneId),
          isNotNull(issues.milestoneId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const totals = new Map<MilestoneId, { total: number; closed: number }>();
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const key = row.milestoneId as MilestoneId;
    const entry = totals.get(key) ?? { total: 0, closed: 0 };
    entry.total += row.value;
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) entry.closed += row.value;
    totals.set(key, entry);
  }

  return new Map(
    [...totals].map(([id, { total, closed }]) => [
      id,
      { total, open: total - closed, closed },
    ]),
  );
}

