/**
 * Project milestones: create, rename, re-date, close and reopen, plus the progress read over the issues each one holds.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived, milestoneNameKey, MAX_OPEN_MILESTONES_PER_PROJECT
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { milestoneNameSchema } from "@/schemas/milestone";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import { toIsoTimestamp } from "@/types/common";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type {
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

/** What a milestone with no live issues reports. */
const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const project = await loadEditableProject(actor, input.orgId, input.projectId);

  const name = cleanName(input.name);
  await assertNameFree(input.orgId, project.id, name, null);
  await assertBelowOpenCap(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and re-dates a milestone, open or closed. Changes announce nothing. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const current = await loadMilestone(input.orgId, input.milestoneId);
  await loadEditableProject(actor, input.orgId, current.projectId);

  const name = input.name === undefined ? undefined : cleanName(input.name);
  if (name !== undefined) {
    await assertNameFree(input.orgId, current.projectId, name, current.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, current.id, {
    name,
    targetDate: input.targetDate,
  });
}

/**
 * Closes an open milestone. Its open live issues move to `moveOpenIssuesTo`
 * (another open milestone of the same project) or out of any milestone when
 * that is `null`. Closed and archived issues stay where they are. Every refusal
 * happens before anything is written.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{
  readonly milestone: Milestone;
  readonly movedIssueIds: readonly IssueId[];
}> {
  assertOrgScope(actor, input.orgId);
  const current = await loadMilestone(input.orgId, input.milestoneId);
  await loadEditableProject(actor, input.orgId, current.projectId);
  if (current.closedAt !== null) throw new MilestoneStateError("closed");

  const target =
    input.moveOpenIssuesTo === null
      ? null
      : await loadMoveTarget(input.orgId, current, input.moveOpenIssuesTo);

  const closed = await milestoneRepo.closeMilestoneRow(
    input.orgId,
    current.id,
    target?.id ?? null,
    toIsoTimestamp(new Date()),
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.milestone.id,
    projectId: closed.milestone.projectId,
    movedToMilestoneId: target?.id ?? null,
    movedIssueIds: closed.movedIssueIds,
  });

  return { milestone: closed.milestone, movedIssueIds: closed.movedIssueIds };
}

/** Reopens a closed milestone, subject to the open-milestone cap. */
export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const current = await loadMilestone(orgId, milestoneId);
  await loadEditableProject(actor, orgId, current.projectId);
  if (current.closedAt === null) throw new MilestoneStateError("already_open");
  await assertBelowOpenCap(orgId, current.projectId);

  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    current.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Open milestones first, then closed; each group by target date (undated last), then oldest first. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);
  const project = await loadReadableProject(actor, orgId, projectId);

  const milestones = await milestoneRepo.listMilestones(orgId, project.id);
  const progress = await milestoneRepo.countMilestoneIssues(orgId, project.id);
  const now = Date.now();

  return [...milestones]
    .sort(compareMilestones)
    .map((milestone) =>
      withProgress(milestone, progress.get(milestone.id) ?? EMPTY_PROGRESS, now),
    );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);
  const milestone = await loadMilestone(orgId, milestoneId);
  await loadReadableProject(actor, orgId, milestone.projectId);

  const progress = await milestoneRepo.countMilestoneIssues(
    orgId,
    milestone.projectId,
    milestone.id,
  );

  return withProgress(
    milestone,
    progress.get(milestone.id) ?? EMPTY_PROGRESS,
    Date.now(),
  );
}

async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  return requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
}

/** Reads need `project:read` only, and work on archived projects too. */
async function loadReadableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
  return project;
}

/** Every milestone write: `project:update`, and the project must not be archived. */
async function loadEditableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

/** The milestone open issues move to: another open milestone of the same project. */
async function loadMoveTarget(
  orgId: OrgId,
  source: Milestone,
  targetId: MilestoneId,
): Promise<Milestone> {
  const target = await milestoneRepo.findMilestoneById(orgId, targetId);
  if (
    target === null ||
    target.id === source.id ||
    target.projectId !== source.projectId
  ) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) throw new MilestoneStateError("closed");
  return target;
}

/** Names are stored trimmed, so a name that is only spaces is as empty as no name. */
function cleanName(name: string): string {
  return milestoneNameSchema.parse(name.trim());
}

/** Names are unique per project, closed milestones included; `exceptId` is the milestone being renamed. */
async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  const taken = await milestoneRepo.findMilestoneByName(orgId, projectId, name);
  if (taken !== null && taken.id !== exceptId) {
    throw new MilestoneStateError("name_taken");
  }
}

async function assertBelowOpenCap(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: number,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isOverdue(milestone, progress, now),
  };
}

/** Open, target date strictly in the past, and still holding open issues. */
