): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: number,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isOverdue(milestone, progress, now),
  };
}

/** Open, target date strictly in the past, and still holding open issues. */
function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: number,
): boolean {
  return (
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    Date.parse(milestone.targetDate) < now &&
    progress.open > 0
  );
}

function compareMilestones(a: Milestone, b: Milestone): number {
  const openFirst = Number(a.closedAt !== null) - Number(b.closedAt !== null);
  if (openFirst !== 0) return openFirst;

  const aDue = a.targetDate === null ? null : Date.parse(a.targetDate);
  const bDue = b.targetDate === null ? null : Date.parse(b.targetDate);
  if (aDue !== bDue) {
    if (aDue === null) return 1;
    if (bDue === null) return -1;
    return aDue - bDue;
  }

  return a.createdAt.localeCompare(b.createdAt);
}

