import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, MilestoneId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import { ZodError } from "zod";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let detachAudit: Unsubscribe;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** Resolves to the error a promise rejects with, so its fields can be checked. */
async function rejectionOf(promise: Promise<unknown>): Promise<unknown> {
  return promise.then(
    () => {
      throw new Error("expected the call to be refused");
    },
    (error: unknown) => error,
  );
}

async function expectRefusal(promise: Promise<unknown>, reason: string) {
  const error = await rejectionOf(promise);
  expect(error).toBeInstanceOf(MilestoneStateError);
  expect((error as MilestoneStateError).reason).toBe(reason);
}

async function newProject(key: string): Promise<ProjectId> {
  const project = await projectService.createProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    name: `Project ${key}`,
    slug: key.toLowerCase(),
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

async function newMilestone(
  projectId: ProjectId,
  name: string,
  targetDate: string | null = null,
) {
  return milestoneService.createMilestone(tenant.actors.admin, {
    orgId: tenant.org.id,
    projectId,
    name,
    targetDate: targetDate === null ? null : toIsoTimestamp(targetDate),
  });
}

async function newIssue(
  projectId: ProjectId,
  title: string,
  milestoneId: MilestoneId | null = null,
  assigneeId: Tenant["userIds"]["admin"] | null = null,
) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title, milestoneId, assigneeId }),
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones", "growth");
  detachAudit = activityService.registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

describe("naming", () => {
  it("stores a trimmed name and refuses a clash that ignores case and surrounding spaces", async () => {
    const projectId = await newProject("NAMES");

    const alpha = await newMilestone(projectId, "  Alpha  ");
    expect(alpha.name).toBe("Alpha");

    await expectRefusal(newMilestone(projectId, "alpha"), "name_taken");
    await expectRefusal(newMilestone(projectId, " ALPHA "), "name_taken");
  });

  it("keeps a closed milestone's name reserved", async () => {
    const projectId = await newProject("RESERVE");
    const beta = await newMilestone(projectId, "Beta");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: beta.id,
      moveOpenIssuesTo: null,
    });

    await expectRefusal(newMilestone(projectId, "beta"), "name_taken");
  });

  it("allows the same name in another project", async () => {
    const first = await newProject("SAMEA");
    const second = await newProject("SAMEB");

    await newMilestone(first, "Launch");
    await expect(newMilestone(second, "Launch")).resolves.toMatchObject({
      name: "Launch",
      projectId: second,
    });
  });

  it("refuses a rename onto a taken name, and allows a rename that only changes case", async () => {
    const projectId = await newProject("RENAME");
    const one = await newMilestone(projectId, "One");
    const two = await newMilestone(projectId, "Two");

    await expectRefusal(
      milestoneService.updateMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: two.id,
        name: "ONE",
      }),
      "name_taken",
    );

    const renamed = await milestoneService.updateMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: one.id,
      name: "one ",
    });
    expect(renamed.name).toBe("one");
  });

  it("treats a name of only spaces as invalid", async () => {
    const projectId = await newProject("BLANK");
    await expect(newMilestone(projectId, "   ")).rejects.toBeInstanceOf(ZodError);
  });

  it("changes the target date, and clears it when given null", async () => {
    const projectId = await newProject("DATES");
    const milestone = await newMilestone(projectId, "Dated", "2030-01-01T00:00:00.000Z");

    const moved = await milestoneService.updateMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      targetDate: toIsoTimestamp("2031-06-01T00:00:00.000Z"),
    });
    expect(moved.targetDate).toBe("2031-06-01T00:00:00.000Z");
    expect(moved.name).toBe("Dated");

    const cleared = await milestoneService.updateMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      targetDate: null,
    });
    expect(cleared.targetDate).toBeNull();
  });
});

describe("open-milestone cap", () => {
  it("refuses an open milestone past the cap, and counts a reopen against it", async () => {
    const projectId = await newProject("CAP");
    const milestones = [];
    for (let index = 0; index < MAX_OPEN_MILESTONES_PER_PROJECT; index += 1) {
      milestones.push(await newMilestone(projectId, `Cap ${index}`));
    }

    await expectRefusal(newMilestone(projectId, "Overflow"), "too_many_open");

    const first = milestones[0];
    if (first === undefined) throw new Error("setup failed");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });

    await expect(newMilestone(projectId, "Overflow")).resolves.toMatchObject({
      name: "Overflow",
    });
    await expectRefusal(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, first.id),
      "too_many_open",
    );
  });
});

describe("closing", () => {
  it("moves open live issues to the target, leaves closed and archived ones, and announces once", async () => {
    const projectId = await newProject("CLOSE");
    const source = await newMilestone(projectId, "Source");
    const target = await newMilestone(projectId, "Target");

    const open = await newIssue(projectId, "Open one", source.id, tenant.userIds.admin);
    const inProgress = await newIssue(projectId, "Open two", source.id);
    const done = await newIssue(projectId, "Done one", source.id);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: done.id,
      status: "done",
    });
    const archived = await newIssue(projectId, "Archived one", source.id);
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, archived.id);

    const closed = capture("milestone.closed");
    const result = await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: target.id,
    });

    expect([...result.movedIssueIds].sort()).toEqual([open.id, inProgress.id].sort());
    expect(result.milestone.closedAt).not.toBeNull();

    expect((await issueRepo.findIssueById(tenant.org.id, open.id))?.milestoneId).toBe(target.id);
    expect((await issueRepo.findIssueById(tenant.org.id, inProgress.id))?.milestoneId).toBe(target.id);
    expect((await issueRepo.findIssueById(tenant.org.id, done.id))?.milestoneId).toBe(source.id);
    expect((await issueRepo.findIssueById(tenant.org.id, archived.id))?.milestoneId).toBe(source.id);

    expect(closed).toHaveLength(1);
    expect(closed[0]).toMatchObject({
      milestoneId: source.id,
      movedToMilestoneId: target.id,
      actorId: tenant.userIds.owner,
    });
    expect([...(closed[0]?.movedIssueIds ?? [])].sort()).toEqual(
      [open.id, inProgress.id].sort(),
    );
  });

  it("alerts each moved issue's assignee once, and never the person who closed", async () => {
    const projectId = await newProject("ALERT");
    const source = await newMilestone(projectId, "Alert source");
    const issue = await newIssue(projectId, "Assigned", source.id, tenant.userIds.admin);
    await newIssue(projectId, "Unassigned", source.id);

    await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: null,
    });

    const forAdmin = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 25,
      cursor: null,
    });
    expect(forAdmin.items).toHaveLength(1);
    expect(forAdmin.items[0]?.href).toBe(`/issues/${issue.id}`);

    const forOwner = await notificationService.listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 25,
      cursor: null,
    });
    expect(forOwner.items).toHaveLength(0);
  });

  it("records the close in the audit log", async () => {
    const projectId = await newProject("AUDIT");
    const source = await newMilestone(projectId, "Audited");

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: null,
    });

    const page = await activityService.listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["milestone.closed"],
      limit: 100,
      cursor: null,
    });
    expect(page.items.find((event) => event.subjectId === source.id)).toMatchObject({
      action: "milestone.closed",
      subjectKind: "milestone",
      projectId,
    });
  });

  it("refuses a closed target, the milestone itself, another project's milestone and an unknown id, changing nothing", async () => {
    const projectId = await newProject("TARGETS");
    const elsewhere = await newProject("ELSEWHERE");
    const source = await newMilestone(projectId, "Refused source");
    const closedTarget = await newMilestone(projectId, "Closed target");
    const foreign = await newMilestone(elsewhere, "Foreign");
    await newIssue(projectId, "Stays put", source.id);

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });

    const closed = capture("milestone.closed");
    const refusal = (targetId: MilestoneId) =>
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: targetId,
      });

    await expectRefusal(refusal(closedTarget.id), "closed");
    await expect(rejectionOf(refusal(source.id))).resolves.toBeInstanceOf(NotFoundError);
    await expect(rejectionOf(refusal(foreign.id))).resolves.toBeInstanceOf(NotFoundError);
    await expect(
      rejectionOf(refusal("ZZZZZZZZZZZZZZZZZZZZZZZZZZ" as MilestoneId)),
    ).resolves.toBeInstanceOf(NotFoundError);

    expect(closed).toHaveLength(0);
    const stillOpen = await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, source.id);
    expect(stillOpen.milestone.closedAt).toBeNull();
    expect(stillOpen.progress.open).toBe(1);
  });

  it("refuses closing a milestone that is already closed", async () => {
    const projectId = await newProject("TWICE");
    const once = await newMilestone(projectId, "Once");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: once.id,
      moveOpenIssuesTo: null,
    });

    await expectRefusal(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: once.id,
        moveOpenIssuesTo: null,
      }),
      "closed",
    );
  });

  it("reopens a closed milestone, and refuses to reopen an open one", async () => {
    const projectId = await newProject("REOPEN");
    const milestone = await newMilestone(projectId, "Reopen me");

    await expectRefusal(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, milestone.id),
      "already_open",
    );

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });
    const reopened = capture("milestone.reopened");

    const back = await milestoneService.reopenMilestone(
      tenant.actors.admin,
      tenant.org.id,
      milestone.id,
    );
    expect(back.closedAt).toBeNull();
    expect(reopened).toHaveLength(1);
    expect(reopened[0]).toMatchObject({ milestoneId: milestone.id, projectId });
  });
});

describe("listing, progress and overdue", () => {
  it("orders open milestones before closed, by target date with undated last, and reports progress", async () => {
    const projectId = await newProject("LIST");
    const past = await newMilestone(projectId, "Past", "2020-01-01T00:00:00.000Z");
    const future = await newMilestone(projectId, "Future", "2999-01-01T00:00:00.000Z");
    const undated = await newMilestone(projectId, "Undated");
    const old = await newMilestone(projectId, "Old", "2019-01-01T00:00:00.000Z");

    const pastOpen = await newIssue(projectId, "Still open", past.id);
    const pastDone = await newIssue(projectId, "Finished", past.id);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: pastDone.id,
      status: "canceled",
    });
    await newIssue(projectId, "Future work", future.id);
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: old.id,
      moveOpenIssuesTo: null,
    });

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );

    expect(listed.map((item) => item.milestone.name)).toEqual([
      "Past",
      "Future",
      "Undated",
      "Old",
    ]);
    expect(listed.find((item) => item.milestone.id === past.id)?.progress).toEqual({
      total: 2,
      open: 1,
      closed: 1,
    });
    expect(listed.find((item) => item.milestone.id === undated.id)?.progress).toEqual({
      total: 0,
      open: 0,
      closed: 0,
    });
    expect(listed.map((item) => item.overdue)).toEqual([true, false, false, false]);
    expect(pastOpen.id).toEqual(expect.any(String));
  });

  it("is overdue only while open, past its target date, and holding open issues", async () => {
    const projectId = await newProject("OVERDUE");
    const milestone = await newMilestone(projectId, "Late", "2020-01-01T00:00:00.000Z");
    const issue = await newIssue(projectId, "Late work", milestone.id);

    const overdue = await milestoneService.getMilestone(
      tenant.actors.member,
      tenant.org.id,
      milestone.id,
    );
    expect(overdue.overdue).toBe(true);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });
    const finished = await milestoneService.getMilestone(
      tenant.actors.member,
      tenant.org.id,
      milestone.id,
    );
    expect(finished.overdue).toBe(false);
  });

  it("leaves archived issues out of the progress counts", async () => {
    const projectId = await newProject("PROGRESS");
    const milestone = await newMilestone(projectId, "Counted");
    await newIssue(projectId, "Live", milestone.id);
    const gone = await newIssue(projectId, "Gone", milestone.id);
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, gone.id);

    const counted = await milestoneService.getMilestone(
      tenant.actors.member,
      tenant.org.id,
      milestone.id,
    );
    expect(counted.progress).toEqual({ total: 1, open: 1, closed: 0 });
  });
});

describe("moving issues", () => {
  it("puts an issue into an open milestone, takes it out, and announces only real changes", async () => {
    const projectId = await newProject("MOVE");
    const milestone = await newMilestone(projectId, "Move target");
    const issue = await newIssue(projectId, "Mover");

    const updated = capture("issue.updated");
    const into = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: milestone.id,
    });
    expect(into.milestoneId).toBe(milestone.id);
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["milestoneId"]);

    const again = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: milestone.id,
    });
    expect(again.milestoneId).toBe(milestone.id);
    expect(updated).toHaveLength(1);

    const out = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(out.milestoneId).toBeNull();
    expect(updated).toHaveLength(2);
  });

  it("refuses a closed milestone, another project's milestone, an archived issue and a stranger", async () => {
    const projectId = await newProject("MOVEREFUSE");
    const elsewhere = await newProject("MOVEELSE");
    const closed = await newMilestone(projectId, "Shut");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await newMilestone(elsewhere, "Abroad");
    const open = await newMilestone(projectId, "Open");
    const issue = await newIssue(projectId, "Subject");

    await expectRefusal(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: closed.id,
      }),
      "closed",
    );
    await expect(
      rejectionOf(
        issueService.setIssueMilestone(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          milestoneId: foreign.id,
        }),
      ),
    ).resolves.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: open.id,
      }),
    ).resolves.toMatchObject({ milestoneId: open.id });

    const bystander = await newIssue(projectId, "Not mine");
    await expect(
      issueService.setIssueMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: bystander.id,
        milestoneId: open.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const archived = await newIssue(projectId, "Shelved");
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, archived.id);
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: archived.id,
        milestoneId: open.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a closed milestone at creation and creates nothing", async () => {
    const projectId = await newProject("CREATEREFUSE");
    const closed = await newMilestone(projectId, "Done with");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });

    const before = await issueRepo.countIssues(tenant.org.id, projectId);
    const created = capture("issue.created");

    await expectRefusal(newIssue(projectId, "Too late", closed.id), "closed");

    expect(await issueRepo.countIssues(tenant.org.id, projectId)).toBe(before);
    expect(created).toHaveLength(0);
  });

  it("puts an issue into an open milestone at creation", async () => {
    const projectId = await newProject("CREATEIN");
    const milestone = await newMilestone(projectId, "Planned");

    const issue = await newIssue(projectId, "Planned work", milestone.id);
    expect(issue.milestoneId).toBe(milestone.id);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id as IssueId);
    expect(stored?.milestoneId).toBe(milestone.id);
  });
});

describe("archived projects, tenancy and permissions", () => {
  it("refuses every milestone change in an archived project but still lists it", async () => {
    const projectId = await newProject("FROZEN");
    const milestone = await newMilestone(projectId, "Frozen");
    await newIssue(projectId, "Inside", milestone.id);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });

    await expect(newMilestone(projectId, "Late")).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.updateMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        name: "Renamed",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const listed = await milestoneService.listMilestones(
      tenant.actors.member,
      tenant.org.id,
      projectId,
    );
    expect(listed).toHaveLength(1);
  });

  it("scopes every operation to the actor's workspace", async () => {
    const other = await createTenant("milestones-other", "growth");
    const foreign = await milestoneService.createMilestone(other.actors.admin, {
      orgId: other.org.id,
      projectId: other.project.id,
      name: "Elsewhere",
      targetDate: null,
    });

    await expect(
      milestoneService.listMilestones(tenant.actors.admin, other.org.id, other.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.getMilestone(tenant.actors.admin, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.createMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: other.project.id,
        name: "Intruder",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets a viewer read milestones but not change them", async () => {
    const projectId = await newProject("ROLES");

    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        projectId,
        name: "Nope",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, projectId),
    ).resolves.toEqual([]);
  });
});

