/** Milestone schemas, and the milestone values the activity and notification enums must accept. */
import { describe, expect, it } from "vitest";
import { createIssueSchema } from "@/schemas/issue";
import {
  closeMilestoneSchema,
  createMilestoneSchema,
  setIssueMilestoneSchema,
  updateMilestoneSchema,
} from "@/schemas/milestone";
import { activityActionSchema, activitySubjectKindSchema } from "@/schemas/activity";
import {
  notificationKindSchema,
  updateNotificationPreferenceSchema,
} from "@/schemas/notification";
import { ORG_A, ALICE } from "../helpers/factories";

const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";
const ISSUE = "01HZZZSSSSSSSSSSSSSSSSSSSS";
const MILESTONE = "01HZZZMMMMMMMMMMMMMMMMMMMM";

describe("schemas/milestone", () => {
  it("defaults the target date and the move target", () => {
    expect(
      createMilestoneSchema.parse({ orgId: ORG_A, projectId: PROJECT, name: "Beta" }),
    ).toMatchObject({ name: "Beta", targetDate: null });

    expect(
      closeMilestoneSchema.parse({ orgId: ORG_A, milestoneId: MILESTONE }),
    ).toMatchObject({ moveOpenIssuesTo: null });
  });

  it("bounds the name to 1 to 80 characters", () => {
    const base = { orgId: ORG_A, projectId: PROJECT };
    expect(createMilestoneSchema.safeParse({ ...base, name: "" }).success).toBe(false);
    expect(createMilestoneSchema.safeParse({ ...base, name: "a".repeat(81) }).success).toBe(false);
    expect(createMilestoneSchema.safeParse({ ...base, name: "a".repeat(80) }).success).toBe(true);
  });

  it("lets an update leave the name and the date alone", () => {
    expect(
      updateMilestoneSchema.parse({ orgId: ORG_A, milestoneId: MILESTONE }),
    ).toEqual({ orgId: ORG_A, milestoneId: MILESTONE });
  });

  it("requires an explicit milestone, null included, when setting an issue's milestone", () => {
    expect(
      setIssueMilestoneSchema.safeParse({ orgId: ORG_A, issueId: ISSUE }).success,
    ).toBe(false);
    expect(
      setIssueMilestoneSchema.parse({ orgId: ORG_A, issueId: ISSUE, milestoneId: null }),
    ).toMatchObject({ milestoneId: null });
  });
});

describe("issue milestone field", () => {
  const base = { orgId: ORG_A, projectId: PROJECT, title: "Fix the link" };

  it("defaults to no milestone and accepts a milestone id", () => {
    expect(createIssueSchema.parse(base)).toMatchObject({ milestoneId: null });
    expect(
      createIssueSchema.parse({ ...base, milestoneId: MILESTONE }),
    ).toMatchObject({ milestoneId: MILESTONE });
    expect(createIssueSchema.safeParse({ ...base, milestoneId: "nope" }).success).toBe(false);
  });
});

describe("audit and alert vocabularies", () => {
  it("accepts the milestone audit actions and subject kind in the filter schema", () => {
    for (const action of ["milestone.created", "milestone.closed", "milestone.reopened"]) {
      expect(activityActionSchema.safeParse(action).success, action).toBe(true);
    }
    expect(activitySubjectKindSchema.safeParse("milestone").success).toBe(true);
  });

  it("accepts the milestone alert kind in the preference schema", () => {
    expect(notificationKindSchema.safeParse("issue_milestone_changed").success).toBe(true);
    expect(
      updateNotificationPreferenceSchema.safeParse({
        orgId: ORG_A,
        userId: ALICE,
        kind: "issue_milestone_changed",
        inApp: true,
        email: false,
        digestOnly: false,
      }).success,
    ).toBe(true);
  });
});

