/** `MilestoneStateError`: its shape, how it is mapped to an app error, and the name key that makes names unique. */
import { describe, expect, it } from "vitest";
import { isDomainError, toAppError } from "@/lib/errors";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";

describe("lib/milestones", () => {
  it("carries its reason and a conflict code", () => {
    const error = new MilestoneStateError("too_many_open");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("conflict");
    expect(error.reason).toBe("too_many_open");
    expect(error.message).toContain("maximum number of open milestones");
  });

  it("is a domain error that maps to a conflict with its reason", () => {
    const error = new MilestoneStateError("name_taken");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({
      code: "conflict",
      meta: { reason: "name_taken" },
    });
  });

  it("keys names without regard to case or surrounding spaces", () => {
    expect(milestoneNameKey("  Sprint 1 ")).toBe(milestoneNameKey("sprint 1"));
    expect(milestoneNameKey("Sprint 1")).not.toBe(milestoneNameKey("Sprint 2"));
  });
});

